function getausdatetimezone() {
    const sydneyNow = new Date(
        new Date().toLocaleString("en-AU", {
            timeZone: "Australia/Sydney"
        })
    );
    const offSet = 11; // 10 for AEST, 11 for AEDT

    return Math.floor(
        (new Date(f('insertdate').get()) - sydneyNow) / offSet * 60 * 60 * 1000
    ) >= 0;
}

function copyq(to,fr) 
{
    var prec = f(fr).domainValues(); 
    for (var i = 0; i < prec.length; i++) {
        var code = prec[i];
        if (f(fr).item(code).toBoolean()) 
        {
            f(to).item(code).set(f(fr).item(code).get());
        }
    }
}



function maskemail(qid) 
{
    var parts = f(qid).get().split('@');
    var local = parts[0];
    var domain = parts[1];

    if (local.length <= 2) {
        return local + '@' + domain;
    }

    return local.substring(0, 2) +
        'x'.repeat(local.length - 2) +
        '@' + domain;
}


function maskmobile(qid) {
    var mobile = f(qid).get();
    return mobile.substring(0, 2) +
           'x'.repeat(Math.max(0, mobile.length - 5)) +
           mobile.substring(mobile. length - 3);
}



function maskname(qid) {
    var name = f(qid).get();

    return name.split(' ').map(function(word) {
        var masked = '';

        for (var i = 0; i < word.length; i++) {
            if (i === 0 || (i % 4 === 0)) {
                masked += word.charAt(i);
            } else {
                masked += '*';
            }
        }

        return masked;
    }).join(' ');
}

function skipcode(qid) {
    var skipCode = "1000";
    if (f(qid).getType() == 'COMPOUND') {
        var form = f(qid);
        var codes = form.domainValues();
        for (var i = 0; i < codes.length; i++) {
            var code = codes[i];
            if (form.item(code).DICHOTOMY) {
                if (!f(qid).toBoolean()) {
                    //Multi select
                    f(qid).item(skipCode).set('1');
                }
            }
            else if (form.item(code).OPEN || form.item(code).NUMERIC) {//do nothing for text box
            }
            else //grid
            {
                if (!f(qid).item(code).toBoolean()) {
                    f(qid).item(code).set(skipCode);
                }
            }
        }
    }
    else if (f(qid).getType() == 'CODED' && !f(qid).toBoolean()) //single select
    {
        f(qid).set(skipCode);
    }
    else {
    }
}

function getProjectSettings(name) {
  const projectSettings = {
    // This might not be the same as the src_job_id. 
    // If you need to dedupe across multiple separate Forsta surveys, you would set them
    // all to have the same value below
    DEDUPE_PROJECT_CODE: "SRC3497M",
    // set as a single string, NO spaces
    //e.g. LinA, ORU, Octopus, Pureprofile, Lightspeed, Open (for open link), Client
    PANEL_NAME: "Client",
    // Set the country code for whehre the survey is running. Is used by RD to detect country mismatches and 
    // block respondents for entering the survey
    // NZ for New Zealand etc (Can only set to one single country)
    COUNTRY_CODE: "AU",
    // Controls whether the screen containing Research Defender is automatically submitted
    // once the API queries have completed or the timeout is reached, whichever happens first.
    //
    // Useful when Research Defender is placed on an intermediate screen and respondents
    // should continue automatically without clicking Next.
    AUTO_SUBMIT: false,
  };
  return projectSettings[name];
}

/*
  Uncomment the relevant config below, appropriate for the sample source being used for the project.
  Currently supported types are:
    - LinA
    - Client sample with/without incentives
    - Non-probability panel / MMM / Polaron
    - Commercial list sample with/without incentives
    - A-BS push-to-web
    - RDD SMS push-to-web
    - Open link / social media **WITHOUT** incentives
    - Open link / social media **WITH** incentives
*/

function getRDConfig(name) {
  const socialMediaTopupValues = ["0", "3", "4", "5"];
  const isSocialMediaTopup = socialMediaTopupValues.includes(GetRespondentValue("TU_source"));

  if (isSocialMediaTopup) {
    const configs = {
      FAIL_ON_API_ERROR: true,
      THREAT_POTENTIAL_THRESHOLD: 29,
      DUPLICATE_SCORE_THRESHOLD: 100,
      COUNTRY_MISMATCH_CHECK: false,
      ACTIVITY_FAIL_ON_API_ERROR: false,
      ACTIVITY_COUNT_THRESHOLD: false,
    };
    return configs[name];

  } else {
    const configs = {
      FAIL_ON_API_ERROR: false,
      THREAT_POTENTIAL_THRESHOLD: false,
      DUPLICATE_SCORE_THRESHOLD: false,
      COUNTRY_MISMATCH_CHECK: false,
      ACTIVITY_FAIL_ON_API_ERROR: false,
      ACTIVITY_COUNT_THRESHOLD: false,
    };
    return configs[name];
  }
}


