// // 	GoTo dhd2_BM
// // End If

// // If dhd2[Cat].dhd2_resp._1 > Month(Now()) and dhd2[Cat].dhd2_resp._2 = Year(Now()) Then
// // 	dhd2[Cat].dhd2_resp.Errors.AddNew("err1","The date entered is in the future. If you don't know the exact date, please enter your best estimate.")
// // 	GoTo dhd2_BM
// // End If


//TBC AGE_W4 not fully derived yet

var qid = CurrentForm();
var age_w4 = "";
var age_w4 = f('AGE_W4').toNumber()
var year_w4 = f('DUM_DOB_Year').toNumber()

var currentYear = new Date().getFullYear();
var currentMonth = new Date().getMonth() + 1;

var minVal = 1945

var year = parseInt(age_w4, 10);

if (year > 0) {
	minVal = currentYear - year
}

if (f(qid).any('1')) {
	var num1 = f(qid + "_1_other").get();
	var re1 = /^\d{1,3}$/

	if (!re1.test(num1) || !(num1 >= 1 && num1 <= 12)) {
		f(qid + "_1_other").set(null)
		RaiseError();
		ClearErrorMessage();
		ClearQuestionErrorMessage();
		AppendQuestionErrorMessage(LangIDs.en_au, 'Please enter a response between 1 and 12 for month');
	}




}
if (f(qid).any('2')) {
	var num2 = f(qid + "_2_other").get();
	var re2 = /^\d{1,4}$/

	if (!re2.test(num2) || !(num2 >= minVal && num2 <= currentYear)) {
		f(qid + "_2_other").set(null)
		RaiseError();
		ClearErrorMessage();
		// ClearQuestionErrorMessage();
		AppendQuestionErrorMessage(LangIDs.en_au, "Please enter a response between " + minVal + " and " + currentYear + " for year");
	}

	if (!f('AGE_W4').toBoolean() || f('AGE_W4').toNumber()==99)
		if (!re2.test(num2) || !(num2 >= 1945 && num2 <= 2026)) {
			errormessage('46');
		}

	if (num2 < f('DUM_DOB_Year').toNumber())
	{
		errormessage('71')
	}

	if (f('DUM_DOB_MONTH').toBoolean())
	{
		if (num2 == f('DUM_DOB_Year').toNumber())
		{
			if (num1 < f('DUM_DOB_MONTH').get())
			{
				errormessage('71')
			}
		}
	}
}
if (f(qid).any('1') && f(qid).any('2')) {
	var num1 = f(qid + "_1_other").get();
	var num2 = f(qid + "_2_other").get();
	if ((num1 > currentMonth && num2 >= currentYear)) 
	{
		f(qid + "_1_other").set(null)
		RaiseError();
		ClearErrorMessage();
		// ClearQuestionErrorMessage();
		AppendQuestionErrorMessage(LangIDs.en_au, "The date entered is in the future. If you don't know the exact date, please enter your best estimate.");
	}
}
if (f(qid).any('1') && f(qid).none('2')) {
	RaiseError();
	ClearErrorMessage();
	// ClearQuestionErrorMessage();
	AppendQuestionErrorMessage(LangIDs.en_au, "Please enter a year as well. If you don't know the exact year, please enter your best estimate.");

}

