        if (f('ghiwgdsi_ghiwgdsi2').any('2')) {st = st.union(set('ghiwgds02'))};
        if (f('ghiwgdsi_ghiwgdsi3').any('2')) {st = st.union(set('ghiwgds03'))};
        if (f('ghiwgdsi_ghiwgdsi4').any('2')) {st = st.union(set('ghiwgds04'))};
        if (f('ghiwgdsi_ghiwgdsi5').any('2')) {st = st.union(set('ghiwgds05'))};
        if (f('ghiwgdsi_ghiwgdsi6').any('2')) {st = st.union(set('ghiwgds06'))};

    return st;
}

