setTimeout(function () {

    const placeholders = {
        DOB_DD: "DD",
        DOB_MM: "MM",
        DOB_YYYY: "YYYY"
    };

    Object.entries(placeholders).forEach(([qid, text]) => {
        document.querySelectorAll(`[id*="${qid}"]`).forEach(el => {
            if (el.tagName === "INPUT") {
                el.placeholder = text;
            }
        });
    });

}, 100);

