var qid = "^CurrentForm()^"

$(document).ready(function() {

    function setQuestionValue(qId, val) {

        Confirmit.page.getQuestion(qId).setValue(val);
    }
	console.log(Confirmit.page.getQuestion(qid));
	let RequestKey
	RequestKey= "^getKleberToken('Kleber_token', true)^" //$("#MBS_Kleber_token_input").val()
	//let autoCompleteInputbox  =$("#ContactAddr_input")
	console.log(RequestKey);
	let autoCompleteInputbox  = $(`#^CurrentForm()^_input`)
	var RetrieveAddressFieldsOpenQ = $(".cf-page__question-list .cf-question.cf-question--open")
	//RetrieveAddressFieldsOpenQ.slice(0).hide()

	autoCompleteInputbox.autocomplete({  
		source:  function( request, response ) {
						$.ajax({
							url: "https://kleber.datatoolscloud.net.au/KleberWebService/DtKleberService.svc/ProcessQueryStringRequest",
							dataType: "jsonp",
							type: "GET",
							contentType: "application/json; charset=utf-8",
							data: {Method:"DataTools.Capture.Address.Predictive.AuPaf.SearchAddress", AddressLine:request.term, ResultLimit:"10", SearchOption:"A002", RequestId:" ", RequestKey:RequestKey, DepartmentCode:"1", OutputFormat:"json" },
							success: function( data ) {  

								response( $.map( data.DtResponse.Result, function( item ) {

									var Output = (item.AddressLine + ", " + item.Locality + ", " + item.State + ", " + item.Postcode);
									return {
										label: Output ,
										value: Output ,
										Output: Output,
										AuPafID:item.RecordId
									}
								}));
							} 
						});
					},
					select: function( event, ui ) { 
						//AuPafID=ui.item ? ui.item.Output.split(",")[0]:"AuPafIdIsNull"
						AuPafID=ui.item.AuPafID
						var RecordId = AuPafID
						var RequestId = ""
						//var RequestKey=$("input[name*='TemporaryKey']").val()
						var DepartmentCode = "1"	
						//var RetrieveAddressFields=$(".cf-page__question-list .cf-question .cf-open-answer__input")
						setQuestionValue("^CurrentForm()^", ui.item.value);	
						//Confirmit.page.getQuestion(qid)._otherValues["1"] = ui.item.value;

					$.ajax({
						url: "https://kleber.datatoolscloud.net.au/KleberWebService/DtKleberService.svc/ProcessQueryStringRequest",
						dataType: "jsonp",
						type: "GET",
						contentType: "application/json; charset=utf-8",
