css.rel = "stylesheet";
css.href = "https://cdn.jsdelivr.net/npm/flatpickr/dist/flatpickr.min.css";
document.head.appendChild(css);

var script = document.createElement("script");
script.src = "https://cdn.jsdelivr.net/npm/flatpickr";
document.head.appendChild(script);

script.onload = function () {

    $("#^CurrentForm()^_input").attr("type", "text");
   setTimeout(function() {
    $(".flatpickr-input").attr("placeholder", "dd/mm/yyyy");
    }, 100);

    flatpickr("#^CurrentForm()^_input", {
        dateFormat: "d/m/Y",
        allowInput: true,
        defaultDate: $("#^CurrentForm()^_input").val() || null,
        onChange: function (selectedDates, dateStr, instance) {
            $("#^CurrentForm()^_input").trigger("change");
        }
    });

};

